


































import Vue from "vue";

export default Vue.extend({
  name: "ImageCarousel",
  props: {
    images: {
      type: Array as () => string[],
      required: true
    }
  },
  data() {
    return {
      currentIndex: 0
    };
  },
  methods: {
    next() {
      this.currentIndex = (this.currentIndex + 1) % this.images.length;
    },
    prev() {
      this.currentIndex = (this.currentIndex - 1 + this.images.length) % this.images.length;
    },
    goTo(index: number) {
      this.currentIndex = index;
    }
  }
});
